      }

      .dialog-text {
        color: var(--color-muted-text);
        margin-bottom: 1.25rem;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

