const fs = require('fs');
const { chromium } = require('playwright');
(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
  const results = {};
  async function audit(name) {
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const r = await page.evaluate(async () => await window.axe.run());
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice')).map(v => ({
      id: v.id,
      impact: v.impact,
      targets: v.nodes.map(n => n.target)
    }));
    const bp = r.violations.filter(v => v.tags.includes('best-practice')).map(v => ({
      id: v.id,
      impact: v.impact,
      targets: v.nodes.map(n => n.target)
    }));
    results[name] = { wcag, bp };
  }
  await page.setContent(html, { waitUntil: 'load' });
  await audit('default');
  await page.click('#delete-trigger');
  await audit('dialog-open');
  await browser.close();
  console.log(JSON.stringify(results));
  if (Object.values(results).some(state => state.wcag.length)) process.exit(1);
})();
