         margin-bottom: 0.75rem;
         font-size: clamp(2rem, 4vw, 3rem);
         line-height: 1.05;
       }

       .intro {
         max-width: 44rem;
         color: var(--color-muted-text);
         font-size: 1.05rem;
       }

       .preview-card,
       .empty-state {
         border: 1px solid var(--color-border);
         border-radius: 1.5rem;
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
         box-shadow: var(--shadow-lg);
         overflow: hidden;
       }

       .preview-layout {
         display: grid;
         grid-template-columns: minmax(0, 1.55fr) minmax(18rem, 1fr);
       }

       .preview-media {
         margin: 0;
         min-height: 100%;
         background: #060a14;
       }

       .preview-media img {
         display: block;
         width: 100%;
         height: 100%;
         min-height: 21rem;
         object-fit: cover;
       }

       .preview-details {
         display: grid;
         gap: 1.5rem;
         padding: 1.75rem;
         background: rgba(9, 14, 28, 0.82);
       }

       .eyebrow {
         color: var(--color-accent);
         font-size: 0.9rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       .meta-list {
         display: grid;
         gap: 0.85rem;
         margin: 0;
       }

       .meta-row {
         display: grid;
         grid-template-columns: 6rem 1fr;
         gap: 1rem;
         padding-bottom: 0.85rem;
         border-bottom: 1px solid rgba(167, 180, 214, 0.18);
       }

       .meta-row dt {
         color: var(--color-muted-text);
       }

       .meta-row dd {
         margin: 0;
         font-weight: 600;
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.875rem;
       }

       button {
         border: 1px solid transparent;
         border-radius: 999px;
         padding: 0.9rem 1.2rem;
         font: inherit;
         font-weight: 700;
         color: var(--color-text);
         background: var(--color-panel-strong);
         cursor: pointer;
         transition: transform 120ms ease, border-color 120ms ease, background-color 120ms ease;
       }

       button:hover {
         transform: translateY(-1px);
       }

       button:focus-visible,
       dialog:focus-visible {
         outline: 3px solid var(--color-focus);
         outline-offset: 3px;
       }

       .ghost-button {
         border-color: var(--color-border);
         background: transparent;
       }

       .trigger,
       .danger-button {
         background: linear-gradient(180deg, var(--color-danger) 0%, var(--color-danger-strong) 100%);
         color: #1b0910;
       }

       .warning {
         display: flex;
         gap: 0.8rem;
         padding: 1rem 1.1rem;
         border: 1px solid #6a3041;
         border-radius: 1rem;
         background: var(--color-danger-surface);
         color: #ffdbe1;
       }

       .warning svg {
         flex: none;
         width: 1.3rem;
         height: 1.3rem;
         margin-top: 0.1rem;
         fill: currentColor;
       }

       dialog {
         width: min(100% - 2rem, 32rem);
         padding: 0;
         border: 1px solid var(--color-border);
         border-radius: 1.4rem;
         background: linear-gradient(180deg, #161f35 0%, #0f172a 100%);
         color: var(--color-text);
         box-shadow: var(--shadow-lg);
       }

       dialog::backdrop {
         background: rgba(3, 6, 12, 0.78);
         backdrop-filter: blur(8px);
       }

       .dialog-content {
         padding: 1.5rem;
       }

       .dialog-title {
         margin-bottom: 0.75rem;
         font-size: 1.5rem;
       }

       .dialog-text {
         color: var(--color-muted-text);
         margin-bottom: 1.25rem;
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         flex-wrap: wrap;
         gap: 0.75rem;
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         clip-path: inset(50%);
         border: 0;
         white-space: nowrap;
       }

       .status {
         min-height: 1.5rem;
         margin-top: 1rem;
         color: var(--color-muted-text);
       }

       .empty-state {
         display: grid;
         gap: 0.75rem;
         place-items: start;
         padding: 2rem;
       }

       .empty-state h2 {
         margin-bottom: 0;
       }

       .empty-state p {
         margin-bottom: 0;
         color: var(--color-muted-text);
         max-width: 34rem;
       }

       @media (max-width: 48rem) {
         .page {
           padding-top: 1.5rem;
         }

         .preview-layout {
           grid-template-columns: 1fr;
         }

         .preview-media img {
           min-height: 16rem;
         }
       }

       @media (forced-colors: active) {
         :root {
           --color-bg: Canvas;
           --color-panel: Canvas;
           --color-panel-strong: ButtonFace;
           --color-text: CanvasText;
           --color-muted-text: CanvasText;
           --color-border: ButtonBorder;
           --color-focus: Highlight;
           --color-danger: ButtonFace;
           --color-danger-strong: ButtonFace;
           --color-danger-surface: Canvas;
           --color-accent: LinkText;
         }

         body,
         .preview-card,
         .empty-state,
         dialog {
           background: Canvas;
         }

         button {
           border-color: ButtonBorder;
         }

         .trigger,
         .danger-button {
           color: ButtonText;
         }

         button:focus-visible,
         dialog:focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <main class="page">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Image library</p>
         <h1 id="page-title">Preview your saved image</h1>
         <p class="intro">
           Review the image details before deciding whether it should remain in your library.
         </p>
       </section>

       <section id="image-card" class="preview-card" aria-labelledby="image-title">
         <div class="preview-layout">
           <figure class="preview-media">
             <img
               src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 900'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' x2='0' y1='0' y2='1'%3E%3Cstop stop-color='%23213663' offset='0'/%3E%3Cstop stop-color='%23091423' offset='1'/%3E%3C/linearGradient%3E%3ClinearGradient id='glow' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%236dc7ff' offset='0'/%3E%3Cstop stop-color='%23784fff' offset='1'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='900' fill='url(%23sky)'/%3E%3Ccircle cx='931' cy='141' r='88' fill='%23f7f0b8' fill-opacity='.9'/%3E%3Cpath d='M0 667 195 540l116 76 172-231 147 136 169-163 139 164 262 145V900H0Z' fill='%23050a13'/%3E%3Cpath d='M0 723 194 600l117 61 175-194 142 103 171-145 139 142 262 156V900H0Z' fill='%230d1730'/%3E%3Cpath d='M381 235c40-61 131-73 186-23 34 32 46 78 39 121 60-3 119 19 158 58 57 57 72 146 38 218-49 104-172 149-275 100-46-22-81-60-99-106-61 22-132 9-183-42-76-76-76-200 0-277 38-38 88-57 137-56Z' fill='url(%23glow)' fill-opacity='.92'/%3E%3Crect x='155' y='678' width='890' height='35' rx='17.5' fill='%23b7e6ff' fill-opacity='.25'/%3E%3C/svg%3E"
               alt="Night landscape artwork with glowing clouds above mountain silhouettes."
             />
           </figure>

           <div class="preview-details">
             <div>
               <p class="eyebrow">Selected image</p>
               <h2 id="image-title">Aurora over silent peaks</h2>
               <p class="intro">
                 A moody landscape illustration with luminous clouds and layered mountain silhouettes.
               </p>
             </div>

             <dl class="meta-list">
               <div class="meta-row">
                 <dt>Type</dt>
                 <dd>Illustration</dd>
               </div>
               <div class="meta-row">
                 <dt>Resolution</dt>
                 <dd>1200 x 900</dd>
               </div>
               <div class="meta-row">
                 <dt>Saved</dt>
                 <dd>May 4, 2026</dd>
               </div>
             </dl>

             <div class="warning">
               <svg viewBox="0 0 24 24" aria-hidden="true">
                 <path d="M12 2 1 21h22L12 2Zm0 6.25a1 1 0 0 1 1 1V14a1 1 0 1 1-2 0V9.25a1 1 0 0 1 1-1Zm0 10a1.25 1.25 0 1 1 0-2.5 1.25 1.25 0 0 1 0 2.5Z" />
               </svg>
               <div>
                 Deleting removes this image from your library. You can close the dialog with
                 <strong>Escape</strong> or choose <strong>Cancel</strong>.
               </div>
             </div>

             <div class="actions">
               <button type="button" class="trigger" id="delete-trigger">Delete image</button>
             </div>
           </div>
         </div>
       </section>

       <section id="empty-state" class="empty-state" hidden aria-labelledby="empty-title">
         <p class="eyebrow">Library updated</p>
         <h2 id="empty-title" tabindex="-1">Image removed</h2>
         <p>This image has been deleted from your library. Select another saved item to continue.</p>
       </section>

       <p id="status-message" class="status" aria-live="polite"></p>
     </main>

     <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
       <div class="dialog-content">
         <h2 id="dialog-title" class="dialog-title">Delete this image from your library?</h2>
         <p id="dialog-description" class="dialog-text">
           This action permanently removes <strong>Aurora over silent peaks</strong> from your saved
           images.
         </p>

         <form method="dialog" class="dialog-actions">
           <button type="submit" value="cancel" class="ghost-button" autofocus>Cancel</button>
           <button type="submit" value="delete" class="danger-button">Delete image</button>
         </form>
       </div>
     </dialog>

     <script>
       const dialog = document.getElementById("delete-dialog");
       const trigger = document.getElementById("delete-trigger");
       const imageCard = document.getElementById("image-card");
       const emptyState = document.getElementById("empty-state");
       const emptyTitle = document.getElementById("empty-title");
       const statusMessage = document.getElementById("status-message");

       trigger.addEventListener("click", () => {
         dialog.showModal();
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue !== "delete") {
           statusMessage.textContent = "";
           return;
         }

         imageCard.hidden = true;
         emptyState.hidden = false;
         statusMessage.textContent = "Image deleted from your library.";
         emptyTitle.focus();
       });
     </script>
   </body>
 </html>
